// @hand-authored - hand-crafted story; not regenerated by gen-stories.
// Card is the "Base Card mechanic": the shared chrome contract (surface / bordered /
// elevated / accent / toneScope / dense, resolved once by resolveCardChrome in
// ../lib/cardChrome.js) that Banner and a framed Collapsible trigger read too - change
// the base here and all three adapt. See the "Base Card" docs section below for the
// chrome contract + the internal slot grid.
import { Card, Button, Icon } from '@corilus/kernel';

const React = window.React;

export default {
  title: 'Core/Layout/Card',
  component: Card,
  tags: ['autodocs'],
  argTypes: {
    surface: { control: 'select', options: ['plain', 'tinted', 'none'], description: 'Body fill: plain is pure white/bright (matches Banner); tinted is a light tone wash (mixed toward white for a faint hint when a tone paints the box, else a neutral sunken tint); none is transparent.', table: { category: 'Appearance', defaultValue: { summary: 'plain' } } },
    bordered: { control: 'boolean', description: 'The hairline border.', table: { category: 'Appearance', defaultValue: { summary: 'true' } } },
    elevated: { control: 'boolean', description: 'A floating ambient drop shadow (--elevation-floating) - the same family as `accent` and a collapsible card.', table: { category: 'Appearance', defaultValue: { summary: 'false' } } },
    accent: { control: 'boolean', description: 'A tone-coloured accent strip on the top edge (needs a `tone` to show colour; toneScope="box").', table: { category: 'Appearance', defaultValue: { summary: 'false' } } },
    toneScope: { control: 'radio', options: ['box', 'content'], description: '"box" lets `tone` also paint background/border/strip. "content" keeps the box neutral while the tone stays available to slot content (e.g. an icon tile).', table: { category: 'Appearance', defaultValue: { summary: 'box' } } },
    dense: { control: 'boolean', description: 'A compact density scope (data-density="compact" on this Card).', table: { category: 'Appearance', defaultValue: { summary: 'false' } } },
    tone: { control: 'text', description: 'Colour identity: a named status (info/success/warning/error), a data tone (data-1..data-6), or any colour/var.', table: { category: 'Appearance' } },
    orientation: { control: 'select', options: ['vertical', 'horizontal'], description: 'Column (default) or row - the row form collapses back to a column inside a narrow container (@container, not the viewport).', table: { category: 'Appearance', defaultValue: { summary: 'vertical' } } },
    size: { control: 'select', options: ['sm', 'md', 'lg'], description: 'Padding density step.', table: { category: 'Appearance', defaultValue: { summary: 'md' } } },
    interactive: { control: 'boolean', description: 'Renders a focusable <button>. Opt-in only.', table: { category: 'Appearance', type: { summary: 'bool' } } },
    selected: { control: 'boolean', description: 'Chosen state (accent border via [data-selected]).', table: { category: 'Appearance', type: { summary: 'bool' } } },
    dragging: { control: 'boolean', description: 'Lifted drag state.', table: { category: 'Appearance', type: { summary: 'bool' } } },
    children: { control: 'text', description: 'Card.Preview / Card.Header / Card.Body / Card.Footer (+ any content). When `detail` is set, this is the always-visible summary.', table: { category: 'Content', type: { summary: 'ReactNode' } } },
  },
  parameters: {
    fitContent: true,
    docs: {
      description: {
        component: [
          'Neutral base card - and the shared **chrome mechanic** the whole card family (Card / Banner / a framed Collapsible trigger) is built on. Owns the wrapper: surface + border + accent-strip + elevation + collapse. Fill Preview / Header / Body / Footer; pass `detail` to make it collapsible.',
          '',
          '**Import**',
          '',
          '```ts',
          "import { Card } from '@corilus/kernel'",
          '```',
          '',
          '## The Base Card mechanic',
          '',
          '`surface` / `bordered` / `elevated` / `accent` / `toneScope` / `dense` are resolved **once**, in JS, by `resolveCardChrome` (`src/lib/cardChrome.js`) into a fixed set of `--card-*` custom properties. CSS never decides chrome by itself - it only *reads* those vars. That is what makes this a shared mechanic rather than a per-component look:',
          '',
          '- **Banner** wraps the same resolver (`edge:"left"`, `neutralFill:"bright"`) - change a chrome rule here and Banner adapts too.',
          '- **Collapsible**’s framed trigger inherits `--card-surface` / `--card-border-color` via ordinary CSS custom-property inheritance, so a Collapsible nested inside a Card reads as the same family, with no props of its own for it.',
          '- Fixes a real bug: the old CSS-only chrome had a class rule and an attribute rule both trying to set the same elevation property at different specificities, so `accent` + the legacy `appearance="elevated"` silently lost the elevation. Now there is exactly one place that decides the final value - see the Chrome matrix section below.',
          '',
          '## The internal slot grid',
          '',
          'The four slots (`Card.Preview` / `Card.Header` / `Card.Body` / `Card.Footer`) are placed with **CSS Grid named areas**, not DOM order - `orientation="vertical"` (default) stacks them in a single column; `orientation="horizontal"` switches to a media column + a stacked text column. An absent slot never leaves a gap (an unoccupied grid row auto-collapses to 0 height; the horizontal media column, being a fixed-width track, uses an explicit `:has()` fallback instead - see `HorizontalNoMedia`).',
          '',
          'A container-query collapse of the horizontal form back to vertical on a narrow container was attempted and reverted: an element cannot be restyled by a `@container` condition evaluated against a container-type it establishes on itself (confirmed empirically here - a pre-existing, identical limitation already affects PatientCard\'s own container queries). A real fix needs a dedicated wrapper element; tracked as a follow-up, not shipped as a rule that silently never fires.',
          '',
          '**Do**',
          '- Compose the base Card + fill slots; don’t hand-roll a card wrapper.',
          '- For a collapsible card, put the teaser in children and the expandable content in `detail`; keep the summary display-only (actions live in detail).',
          '- Use `accent` (needs a tone) for the vibrant top bar; the accent + icon-tile carry the colour so the body stays light and text stays AA.',
          '',
          '**Don’t**',
          '- Nest an interactive Card inside another, or put a button/link in a collapsible card\'s summary (button-in-button).',
        ].join('\n'),
      },
    },
  },
};

// ── Icon in a tinted tile (the reference's leading treatment) ──
const IconTile = ({ children }) => (
  <span style={{
    width: 40, height: 40, borderRadius: 'var(--density-radius)',
    display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
    background: 'var(--card-tone-tint-strong, var(--surface-sunken))',
    color: 'var(--card-tone-text, var(--text-muted))',
  }}>{children}</span>
);

// ── A tone status label (dot + text) reading the card tone ──
const StatusText = ({ children }) => (
  <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, color: 'var(--card-tone-text, var(--text-muted))', fontWeight: 'var(--type-weight-semibold)', fontSize: 'var(--typography-caption-md-font-size)' }}>
    <span style={{ width: 7, height: 7, borderRadius: 999, background: 'currentColor' }} />
    {children}
  </span>
);

export const Playground = {
  args: { surface: 'plain', bordered: true, elevated: true, accent: true, toneScope: 'box', dense: false, tone: 'info', orientation: 'vertical', size: 'md', interactive: false, selected: false, dragging: false },
  render: (args) => (
    <div style={{ maxWidth: 380 }}>
      <Card {...args}>
        <Card.Header
          leading={<IconTile>{Icon.heart({ size: 18 })}</IconTile>}
          title="Blood pressure"
          description="152/94 mmHg — elevated 9 days"
        />
      </Card>
    </div>
  ),
};

// Overview hero: the tone matrix at a glance (accent + elevated - the shared floating
// shadow family).
export const Gallery = {
  parameters: { controls: { disable: true } },
  render: () => (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 260px)', gap: '0.75rem' }}>
      {[
        { tone: undefined, label: 'neutral' },
        { tone: 'info', label: 'info' },
        { tone: 'success', label: 'success' },
        { tone: 'warning', label: 'warning' },
        { tone: 'error', label: 'error' },
        { tone: 'data-3', label: 'data-3' },
      ].map(({ tone, label }) => (
        <Card key={label} elevated accent tone={tone}>
          <Card.Header
            leading={<IconTile>{Icon.chart({ size: 18 })}</IconTile>}
            title={label}
            description="accent + elevated"
          />
        </Card>
      ))}
    </div>
  ),
};

// ── labeled cell so the matrix reads as a decision table, not a wall of cards ──
const Cell = ({ label, children }) => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: '0.35rem' }}>
    <span style={{ fontFamily: 'var(--typography-caption-md-font-family)', fontSize: 'var(--typography-caption-md-font-size)', color: 'var(--text-muted)' }}>{label}</span>
    {children}
  </div>
);

// The chrome matrix, rendered as labelled cells (mirrors Banner's own Gallery) so a
// reviewer can eyeball whether resolveCardChrome tells the truth - including the
// combination that used to be B-54's known bug.
