// The reference "vitals" pattern: collapsible cards, one open at a time (accordion via
// the controlled expanded/onExpandedChange triad), vibrant strip + icon tile on light bodies.
const VITALS = [
  { id: 'bp', tone: 'error', icon: Icon.heart, title: 'Blood Pressure', status: 'Increasing', value: '152/94', unit: 'mmHg', teaser: '132/82 → 152/94 mmHg — elevated 9 consecutive days' },
  { id: 'hr', tone: 'success', icon: Icon.heart, title: 'Heart Rate', status: 'Stable', value: '74', unit: 'bpm', teaser: '72 → 74 bpm — resting rate unchanged' },
  { id: 'wt', tone: 'warning', icon: Icon.chart, title: 'Weight', status: 'Caution', value: '84.1', unit: 'kg', teaser: '+2.1 kg over 3 weeks — +3% since last visit' },
  { id: 'o2', tone: 'data-1', icon: Icon.chart, title: 'Oxygen Saturation', status: 'Normal', value: '98', unit: '%', teaser: '97 → 98% — within expected range' },
];

function VitalsDemo() {
  const [openId, setOpenId] = React.useState('bp');
  return (
    <div style={{ maxWidth: 420, display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
      {VITALS.map((v) => (
        <Card
          key={v.id}
          accent
          tone={v.tone}
          expanded={openId === v.id}
          onExpandedChange={(open) => setOpenId(open ? v.id : null)}
          detail={
            <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>
              <div style={{ height: 96, borderRadius: 'var(--density-radius)', background: 'var(--card-tone-tint, var(--surface-sunken))', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--card-tone-text, var(--text-muted))', fontSize: 'var(--typography-caption-md-font-size)' }}>
                trend chart (slotted content)
              </div>
              <Button size="sm" variant="secondary" tone={v.tone.startsWith('data') ? undefined : v.tone}>Review details</Button>
            </div>
          }
        >
          <Card.Header
            leading={<IconTile>{v.icon({ size: 18 })}</IconTile>}
            title={<span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>{v.title} <StatusText>{v.status}</StatusText></span>}
            description={<><span style={{ fontSize: 'var(--typography-title-md-font-size)', fontWeight: 'var(--type-weight-bold)', color: 'var(--text-default)' }}>{v.value}</span> <span style={{ color: 'var(--text-faint)' }}>{v.unit}</span><div style={{ marginTop: 2 }}>{v.teaser}</div></>}
          />
        </Card>
      ))}
    </div>
  );
}

export const CollapsibleVitals = {
  parameters: { controls: { disable: true } },
  render: () => <VitalsDemo />,
};

// A horizontal media card: the internal slot grid places Preview as a left column
// spanning Header/Body/Footer's stacked rows, by named grid-area (not DOM order).
// NOTE: a container-query collapse back to vertical on a narrow container was
// attempted and reverted - self-styling an element from a @container condition
// evaluated against a container-type IT establishes on itself does not fire in this
// browser (confirmed; a pre-existing, identical bug already exists in PatientCard's
// own container queries) - a real fix needs a wrapper element and is a follow-up.
export const HorizontalMedia = {
  parameters: { controls: { disable: true } },
  render: () => (
    <div style={{ maxWidth: 480 }}>
      <Card orientation="horizontal" elevated>
        <Card.Preview>
          <div style={{ width: '100%', height: '100%', minHeight: 120, background: 'var(--surface-sunken)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-faint)' }}>media</div>
        </Card.Preview>
        <Card.Header title="Horizontal card" description="Media column + stacked text, placed by named grid-area." />
        <Card.Footer><Button size="sm" variant="secondary">Learn more</Button></Card.Footer>
      </Card>
    </div>
  ),
};

// The same card with NO Preview: the horizontal template's fixed-width media column
// would otherwise leave a permanent empty gutter (a fixed-width COLUMN track doesn't
// auto-collapse the way an empty ROW does) - the :has() fallback drops it entirely.
export const HorizontalNoMedia = {
  parameters: { controls: { disable: true } },
  render: () => (
    <div style={{ maxWidth: 480 }}>
      <Card orientation="horizontal" elevated>
        <Card.Header title="Horizontal, no media" description="Falls back to the vertical single-column template - no empty gutter." />
        <Card.Footer><Button size="sm" variant="secondary">Learn more</Button></Card.Footer>
      </Card>
    </div>
  ),
};

// ── Elevation ladder ────────────────────────────────────────────────────────
// The four shadow rungs, plus how the card's interaction STATES map onto them.
// Because :hover/:active can't be driven reliably headless, each state cell forces
// its elevation via an inline --card-elevation so the levels are visible statically
// (the live hover/press behaviour is the same value applied on the real state).
const ELEVATION_RUNGS = [
  { name: 'raised', role: 'tight contact — grounded card, or the PRESSED/active state' },
  { name: 'floating', role: 'gentle resting lift — an elevated / accent / collapsible card AT REST' },
  { name: 'overlay', role: 'menus, popovers, toasts — and the card HOVER state' },
  { name: 'modal', role: 'dialogs — and the card DRAGGED state' },
];
const CARD_STATES = [
  { label: 'rest (flat)', varVal: '0 0 #0000' },
  { label: 'rest (elevated)', varVal: 'var(--elevation-floating)' },
  { label: 'hover', varVal: 'var(--elevation-overlay)' },
  { label: 'active / press', varVal: 'var(--elevation-raised)' },
  { label: 'dragged', varVal: 'var(--elevation-modal)' },
];

export const Elevation = {
  parameters: { controls: { disable: true } },
  render: () => (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem', maxWidth: 620 }}>
      <div>
        <h4 style={{ margin: '0 0 0.75rem' }}>The four shadow rungs (a monotonic ladder)</h4>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          {ELEVATION_RUNGS.map((r) => (
            <div key={r.name} style={{ display: 'grid', gridTemplateColumns: '150px 1fr', gap: '1rem', alignItems: 'center' }}>
              <div style={{ height: 56, borderRadius: 'var(--density-radius)', background: 'var(--surface-bright)', boxShadow: `var(--elevation-${r.name})`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: 'var(--typography-label-md-font-family)', fontWeight: 'var(--type-weight-semibold)' }}>{r.name}</div>
              <span style={{ fontSize: 'var(--typography-caption-md-font-size)', color: 'var(--text-muted)' }}>{r.role}</span>
            </div>
          ))}
        </div>
      </div>
      <div>
        <h4 style={{ margin: '0 0 0.25rem' }}>Card interaction states → rung</h4>
        <p style={{ margin: '0 0 0.75rem', fontSize: 'var(--typography-caption-md-font-size)', color: 'var(--text-muted)' }}>
          Each cell forces its elevation statically so you can compare the levels. Live, these apply on hover / :active / drag with a gentle ease-out shift.
        </p>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))', gap: '1.25rem' }}>
          {CARD_STATES.map((s) => (
            <div key={s.label} style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem' }}>
              <span style={{ fontSize: 'var(--typography-caption-md-font-size)', color: 'var(--text-muted)' }}>{s.label}</span>
              <div className="krnl-card" style={{ '--card-elevation': s.varVal, margin: 0 }}>
                <Card.Body>Card</Card.Body>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  ),
};

// ── Base-card anatomy ───────────────────────────────────────────────────────
// Card is the base of the whole family; every specialised card fills these regions.
// Body is the only region that's conceptually required; everything else is optional.
// A numbered badge keyed to the right-hand legend. `inset` places the badge INSIDE the
// region (for Card.Preview, which clips overflow so a negative-offset badge would be cut);
// the others sit in the padding gutter at a negative offset without clipping.
const AnnotatedRegion = ({ n, inset, children }) => (
  <div style={{ position: 'relative', outline: '1px dashed var(--border-subtle)', outlineOffset: 2, borderRadius: 4 }}>
    <span style={{ position: 'absolute', top: inset ? 6 : -9, left: inset ? 6 : -9, width: 18, height: 18, borderRadius: 999, background: 'var(--action-accent)', color: 'var(--text-on-accent, #fff)', fontSize: 11, fontWeight: 700, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', zIndex: 2 }}>{n}</span>
    {children}
  </div>
);

export const Anatomy = {
  parameters: {
    controls: { disable: true },
    docs: { description: { story: 'Card is the base of the whole card family - Banner, PatientCard, and specialised cards all compose these same regions and inherit the shared chrome. Fill the slots you need; `Card.Body` is the only conceptually required region, the rest are optional.' } },
  },
  render: () => (
    <div style={{ display: 'grid', gridTemplateColumns: '340px 1fr', gap: '2rem', alignItems: 'start', maxWidth: 720 }}>
      <Card elevated style={{ margin: 0 }}>
        <Card.Preview>
          <AnnotatedRegion n={1} inset>
            <div style={{ width: '100%', minHeight: 90, background: 'var(--surface-sunken)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-faint)' }}>media / cover</div>
          </AnnotatedRegion>
        </Card.Preview>
        <AnnotatedRegion n={2}>
          <Card.Header
            leading={<span style={{ width: 36, height: 36, borderRadius: 'var(--density-radius)', background: 'var(--surface-sunken)', display: 'inline-flex', alignItems: 'center', justifyContent: 'center' }}>{Icon.heart({ size: 18 })}</span>}
            title="Title"
            description="leading · title / description · action"
            action={<Button size="sm" variant="secondary">Action</Button>}
          />
        </AnnotatedRegion>
        <AnnotatedRegion n={3}>
          <Card.Body><span style={{ color: 'var(--text-muted)', fontSize: 'var(--typography-body-sm-font-size)' }}>Body — the main content region.</span></Card.Body>
        </AnnotatedRegion>
        <AnnotatedRegion n={4}>
          <Card.Footer><Button size="sm" variant="secondary">Cancel</Button><Button size="sm">Confirm</Button></Card.Footer>
        </AnnotatedRegion>
      </Card>
      <div>
        <h4 style={{ margin: '0 0 0.5rem' }}>Regions</h4>
        <ol style={{ margin: 0, paddingLeft: '1.2rem', display: 'flex', flexDirection: 'column', gap: '0.6rem', fontSize: 'var(--typography-body-sm-font-size)', color: 'var(--text-muted)' }}>
          <li><b style={{ color: 'var(--text-default)' }}>Card.Preview</b> — edge-to-edge media / cover. Optional.</li>
          <li><b style={{ color: 'var(--text-default)' }}>Card.Header</b> — a flex row: leading (icon/avatar) · title + description · trailing action. Optional.</li>
          <li><b style={{ color: 'var(--text-default)' }}>Card.Body</b> — the main content. The one region a card is really about.</li>
          <li><b style={{ color: 'var(--text-default)' }}>Card.Footer</b> — an actions row. Optional.</li>
        </ol>
        <p style={{ margin: '1rem 0 0', fontSize: 'var(--typography-caption-md-font-size)', color: 'var(--text-faint)' }}>
          Regions are placed by CSS-Grid named areas (not DOM order), so orientation="horizontal" re-lays the same slots as a media column beside the text. Chrome (surface / border / accent / elevation) is shared with Banner via one resolver - see the Docs page.
        </p>
      </div>
    </div>
  ),
};
